  const [filter,setFilter]=useState(null)
  const [categories,setCategories]=useState(['All'])

  useEffect(()=>{

    console.log(filter)

  },[filter])

  useEffect(()=>{

    data.forEach((item,index)=>{
      setCategories(prev=>([...prev,item.category]))
    })

  },[])
  return (
    <div className="App">
      <Filters setFilter={ setFilter } categories={ categories }/>
      {/* <Catalog/> */}
    </div>
  );
}

export default App;
